{"script":"() => {
  // Get the full page description
  const descriptionElements = document.querySelectorAll('[role="presentation"]');
  let description = '';
  descriptionElements.forEach(el => {
    description += el.textContent + '\n';
  });

  // Get the course title and key info
  const title = document.title;
  const h1 = document.querySelector('h1, h2');

  return {
    title: title,
    h1: h1 ? h1.textContent : null,
    description: description.substring(0, 2000)
  };
}"}

